def queue_source():
    source = Path(__file__).with_name("ValMAXListWorkQueue.qml").read_text("utf-8").replace("\r\n", "\n")
    if hashlib.sha256(source.encode()).hexdigest() != QUEUE_SHA256:
        raise ValueError("List work queue QML/source mismatch")
    return source

def checked(source, name):
    if type(source) is not str:
        raise ValueError("List work queue requires text")
    source = source.replace("\r\n", "\n")
    if hashlib.sha256(source.encode("utf-8")).hexdigest() != PINS[name]:
        raise ValueError("List work queue source/version/order mismatch")
    return source

def transform(source, name):
    source = checked(source, name)
    for old, new in EDITS[name]:
        if source.count(old) != 1:
            raise ValueError("List work queue anchor drift")
        source = source.replace(old, new, 1)
    return source

def reverse(source, name):
    for old, new in reversed(EDITS[name]):
        if source.count(new) != 1:
            raise ValueError("List work queue output drift")
        source = source.replace(new, old, 1)
    return checked(source, name)

def transform_sources(sources):
    if type(sources) is not dict or not PINS.keys() <= sources.keys():
        raise ValueError("Native list work queue resources missing")
    result = dict(sources)
    for name in PINS:
        result[name] = transform(result[name], name)
    return result
